tokens.css:
--color-bg: #1a1609;
--color-surface: #272010;
--color-text: #f7f2e4;
--color-text-muted: #a79e88;
--color-border: #3d3420;
--color-primary: #f2c94c;
--color-on-primary: #1a1609;
--color-accent: #e07a5f;
--color-on-accent: #1a1609;
--font-display: "Bodoni Moda", Georgia, serif;
--font-body: "Hanken Grotesk", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 18px;
--text-lg: 23px;
--text-xl: 28px;
--text-2xl: 35px;
--text-3xl: 44px;
--radius-control: 6px;
--radius-card: 12px;
--space-section: 120px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
